private static Object convertField(GenericData model, JsonNode datum, Schema.Field field) {
    try {
      Object value = convertToAvro(model, datum, field.schema());
      if (value != null || Schemas.nullOk(field.schema())) {
        return value;
      } else {
        return model.getDefaultValue(field);
      }
    } catch (RecordException e) {
      // add the field name to the error message
      throw new RecordException(String.format("Cannot convert field %s", field.name()), e);
    } catch (AvroRuntimeException e) {
      throw new RecordException(
          String.format("Field %s: cannot make %s value: '%s'", field.name(), field.schema(), datum), e);
    }
  }

@SuppressWarnings("unchecked")
  public AvroJsonReader(InputStream stream, Schema schema) {
    this.stream = stream;
    this.schema = schema;
    this.model = GenericData.get();
    this.iterator = Iterators.transform(
        AvroJson.parser(stream), node -> (E) AvroJson.convertToAvro(model, node, AvroJsonReader.this.schema));
  }

