    WriterVersionResult result = writerVersionResult;
    if (result == null) {
      synchronized (this) {
        result = writerVersionResult;
        if (result == null) {
          result = parseCreatedBy();
          writerVersionResult = result;
        }
      }
    }
    if (result.versionParseException != null) {
