public static ColumnPath get(String... path) {
    return paths.canonicalize(new ColumnPath(path));
  }

/**
   * Create an index cache for the given file reader
   *
   * @param fileReader        the file reader
   * @param columns           the columns that need to do cache
   * @param cacheStrategy     the cache strategy, supports NONE and PREFETCH_BLOCK
   * @param freeCacheAfterGet whether free the given index cache after calling the given get method
   * @return the index cache
   */
static IndexCache create(
      ParquetFileReader fileReader,
      Set<ColumnPath> columns,
      CacheStrategy cacheStrategy,
      boolean freeCacheAfterGet) {
    if (cacheStrategy == CacheStrategy.NONE) {
      return new NoneIndexCache(fileReader);
    } else if (cacheStrategy == CacheStrategy.PREFETCH_BLOCK) {
      return new PrefetchIndexCache(fileReader, columns, freeCacheAfterGet);
    } else {
      throw new UnsupportedOperationException("Unknown cache strategy: " + cacheStrategy);
    }
  }

/**
   * Set the current BlockMetadata
   */
void setBlockMetadata(BlockMetaData currentBlockMetadata) throws IOException;

/**
   * Clean the cache
   */
void clean();

/**
   * start a block
   *
   * @param recordCount the record count in this block
   * @throws IOException if there is an error while writing
   */
public void startBlock(long recordCount) throws IOException {
    withAbortOnFailure(() -> {
      state = state.startBlock();
      LOG.debug("{}: start block", out.getPos());
      //    out.write(MAGIC); // TODO: add a magic delimiter

      alignment.alignForRowGroup(out);

      currentBlock = new BlockMetaData();
      currentRecordCount = recordCount;

      currentColumnIndexes = new ArrayList<>();
      currentOffsetIndexes = new ArrayList<>();

      currentBloomFilters = new HashMap<>();
    });
  }

/**
   * ends a block once all column chunks have been written
   *
   * @throws IOException if there is an error while writing
   */
public void endBlock() throws IOException {
    withAbortOnFailure(() -> {
      if (currentRecordCount == 0) {
        throw new ParquetEncodingException("End block with zero record");
      }

      state = state.endBlock();
      LOG.debug("{}: end block", out.getPos());
      currentBlock.setRowCount(currentRecordCount);
      currentBlock.setOrdinal(blocks.size());
      blocks.add(currentBlock);
      columnIndexes.add(currentColumnIndexes);
      offsetIndexes.add(currentOffsetIndexes);
      bloomFilters.add(currentBloomFilters);
      currentColumnIndexes = null;
      currentOffsetIndexes = null;
      currentBloomFilters = null;
      currentBlock = null;
    });
  }

