   *
   * @param s the short to append
   */
  public void appendShort(short s) {
    onAppend();
    checkCapacity(1 /* header size */ + 2);
    writeBuffer[writePos] = VariantUtil.HEADER_INT16;
    VariantUtil.writeLong(writeBuffer, writePos + 1, s, 2);
    writePos += 3;
  }

  /**
