   *
   * @param b the byte to append
   */
  public void appendByte(byte b) {
    onAppend();
    checkCapacity(1 /* header size */ + 1);
    writeBuffer[writePos] = VariantUtil.HEADER_INT8;
    VariantUtil.writeLong(writeBuffer, writePos + 1, b, 1);
    writePos += 2;
  }

  /**
