          } else if (cmp > 0) {
            high = mid - 1;
          } else {
            int offset = VariantUtil.readUnsignedLittleEndian(
                value, offsetStart + info.offsetSize * mid, info.offsetSize);
            return childVariant(VariantUtil.slice(value, dataStart + offset));
